import express from "express";
import { createExpense, deleteExpense, getExpenseById, getGroupBalances, joinExpense, leaveExpense, removeExpenseMember, updateExpense, markPaymentAsCompletedByOwer, getPendingPaymentNotifications, getPaymentStatus, resetPaymentStatus, paymentConfirmedByReceiverFromNotification, paymentConfirmedByReceiverFromMarkAsPaid, } from "../controllers/expenseController.js";
import { checkAuth } from "../middlewares/authMiddleware.js";
const router = express.Router();
router.get("/payment-status", checkAuth, getPaymentStatus);
router.post("/reset-payment-status", checkAuth, resetPaymentStatus);
router.post("/create", checkAuth, createExpense);
router.get("/:id", checkAuth, getExpenseById);
router.put("/:id", checkAuth, updateExpense);
router.delete("/:id", checkAuth, deleteExpense);
router.post("/join/:id", checkAuth, joinExpense);
router.get("/balances/:id", checkAuth, getGroupBalances);
router.post("/leave/:id", checkAuth, leaveExpense);
router.post("/remove/:id", checkAuth, removeExpenseMember);
router.get("/notifications/:userId", checkAuth, getPendingPaymentNotifications);
router.post("/payment-completed-by-ower", checkAuth, markPaymentAsCompletedByOwer);
router.post("/payment-confirmed-by-receiver-via-notification", checkAuth, paymentConfirmedByReceiverFromNotification);
router.post("/payment-confirmed-by-receiver-via-mark-as-paid", checkAuth, paymentConfirmedByReceiverFromMarkAsPaid);
export default router;
